  function renderDoctoralCouncils(page){
    if(new URL(page.url).pathname!=='/doktorski-spetsializovani-vcheni-rady')return false;
    const source=document.createElement('div');source.append(...readableFragment(page.html,page.url));
    const headings=[...source.querySelectorAll('h2')].filter(n=>/^Д\s*\d+\.\d+\.\d+$/.test(n.textContent.trim()));
    if(!headings.length)return false;
    const list=document.createElement('div');list.className='doctoral-list';
    const normalized=n=>n.textContent.replace(/\s+/g,' ').trim();
    function field(parent,label,value){if(!value)return;const p=document.createElement('p'),strong=document.createElement('strong');strong.textContent=label+': ';p.append(strong,value);parent.append(p);}
    for(const heading of headings){
      const code=normalized(heading),nodes=[];let next=heading.nextElementSibling;
      while(next&&!headings.includes(next)){nodes.push(next);next=next.nextElementSibling;}
      const specialties=[],fields=[];let inSpecialties=false;let detailUrl=null;
      for(const node of nodes){
        const text=normalized(node);if(!text||/^_+$/.test(text))continue;
        const detailsLink=[...node.querySelectorAll('a[href]')].find(a=>a.textContent.includes('Детальніше'));if(detailsLink){detailUrl=detailsLink.href;continue;}
        if(/^Спеціальн(?:ості|ість)\s*:/.test(text)){inSpecialties=true;continue;}
        const match=text.match(/^([^:]+):\s*(.*)$/);
        if(match){inSpecialties=false;let value=match[2];const label=match[1];
          if(/^E-mail/i.test(label)){
            const link=node.querySelector('a[href]');if(link){const url=new URL(link.href);const hex=url.pathname==='/cdn-cgi/l/email-protection'?url.hash.slice(1):'';
              if(/^(?:[a-f0-9]{2})+$/i.test(hex)){const bytes=hex.match(/../g).map(h=>parseInt(h,16));const decoded=bytes.slice(1).map(b=>String.fromCharCode(b^bytes[0])).join('');if(/^[\w.+-]+@[\w.-]+$/.test(decoded))value=decoded;}
            }
            if(value.includes('protected'))value='';
          }
          if(value)fields.push({label,value});
        }else if(inSpecialties&&/^\d{2}\.\d{2}\.\d{2}\s/.test(text))specialties.push(text);
      }
      const card=document.createElement('details');card.className='council-card doctoral-card';
      const summary=document.createElement('summary'),badge=document.createElement('span');badge.className='council-badge';badge.textContent=code;summary.append(badge);
      const preview=document.createElement('span');preview.className='council-candidate doctoral-specialties';
      for(const specialty of specialties){const line=document.createElement('span');line.textContent=specialty.replace(/^\d{2}\.\d{2}\.\d{2}\s*/,'');preview.append(line);}summary.append(preview);card.append(summary);
      const body=document.createElement('div');body.className='council-body';
      const specialtyTitle=document.createElement('h3');specialtyTitle.className='doctoral-detail-title';specialtyTitle.textContent=specialties.length===1?'Спеціальність':'Спеціальності';body.append(specialtyTitle);
      const ul=document.createElement('ul');ul.className='doctoral-specialty-list';for(const specialty of specialties){const li=document.createElement('li');const specialtyCode=specialty.match(/^\d{2}\.\d{2}\.\d{2}/)?.[0];const passport=snapshot?.councils?.passports?.[code]?.[specialtyCode]||doctoralPassports[code]?.[specialtyCode];if(passport){li.className='has-passport';const link=document.createElement('a');link.className='doctoral-passport';link.href=passport;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label',specialty+' - відкрити паспорт спеціальності PDF у новій вкладці');const label=document.createElement('span');label.textContent=specialty;const arrow=document.createElement('span');arrow.className='doctoral-passport-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent='↗';link.append(label,arrow);li.append(link);}else li.textContent=specialty;ul.append(li);}body.append(ul);
      const composition=snapshot?.councils?.membership?.[code]||doctoralMembership[code];
      const leaders=composition?.persons?.filter(p=>p.role!=='Член ради').map(p=>({label:p.role,value:p.name}))||fields.filter(item=>/^(?:Голова ради|Заступник|Вчений секретар)/i.test(item.label));
      function section(title){const fold=document.createElement('details');fold.className='doctoral-fold';const summary=document.createElement('summary');summary.textContent=title;fold.append(summary);body.append(fold);return fold;}
      function personBlock(name,role){const block=document.createElement('section');block.className='doctoral-person';if(role&&role!=='Член ради'){const label=document.createElement('p');label.className='doctoral-person-role';label.textContent=role;block.append(label);}const fullName=document.createElement('p');fullName.className='doctoral-person-name';fullName.textContent=name;block.append(fullName);return block;}
      const leadershipFold=section('Керівництво ради');
      if(leaders.length){const grid=document.createElement('div');grid.className='doctoral-leaders';for(const leader of leaders)grid.append(personBlock(leader.value,leader.label));leadershipFold.append(grid);}
      else{const note=document.createElement('p');note.textContent='Відомості про керівництво ще не додано';leadershipFold.append(note);}
      const compositionFold=section('Члени ради');
      if(composition?.persons?.length){const grid=document.createElement('div');grid.className='doctoral-members';for(const person of composition.persons.filter(p=>p.role==='Член ради'))grid.append(personBlock(person.name,person.role));compositionFold.append(grid);}
      else{const note=document.createElement('p');note.textContent='Відомості про склад ще не додано';compositionFold.append(note);}
      const about=document.createElement('details');about.className='doctoral-about';const aboutTitle=document.createElement('summary');aboutTitle.className='secondary';aboutTitle.textContent='Відомості про раду ▾';about.append(aboutTitle);const aboutContent=document.createElement('div');aboutContent.className='doctoral-about-content';about.append(aboutContent);body.append(about);
      for(const item of fields){
        if(/^(?:Голова ради|Заступник|Вчений секретар)/i.test(item.label))continue;
        if(/^Контактний телефон|^E-mail/i.test(item.label)){
          const p=document.createElement('p'),label=document.createElement('strong');label.textContent=item.label+': ';p.append(label);
          const link=document.createElement('a');link.textContent=item.value;link.href=/^E-mail/i.test(item.label)?'mailto:'+item.value:'tel:'+item.value.replace(/[^+\d]/g,'').replace(/^0/,'+380');p.append(link);aboutContent.append(p);
        }else field(aboutContent,item.label,item.value);
      }
      const archive=document.createElement('details');archive.className='doctoral-archive';
      const archiveTitle=document.createElement('summary');archiveTitle.textContent='Захисти дисертацій у раді';archive.append(archiveTitle);
      const archiveContent=document.createElement('div');archiveContent.className='doctoral-archive-content';archive.append(archiveContent);
      const years=Object.entries(snapshot?.councils?.doctoralDefenses?.[code]??doctoralDefenses[code]??{}).sort((a,b)=>parseInt(b[0])-parseInt(a[0]));
      if(!years.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='На сайті ще немає оприлюднених записів про захисти.';archiveContent.append(empty);}
      for(const [year,defenses] of years){
        const yearFold=document.createElement('details');yearFold.className='doctoral-archive-year';const yearTitle=document.createElement('summary');yearTitle.textContent=year;yearFold.append(yearTitle);
        const items=document.createElement('ul');yearFold.append(items);
        for(const [fullName,url] of defenses){
          const item=document.createElement('li');const row=document.createElement(url?'a':'span');row.className='doctoral-defense';row.title=fullName;
          const label=document.createElement('span');label.textContent=fullName.replace(/\s+[А-ЯІЇЄҐ][а-яіїєґ’'ʼ-]*(?:ович|евич|йович|іч|івна|ївна|овна|ична)\s*$/u,'');row.append(label);
          if(url){row.href=url;row.target='_blank';row.rel='noopener noreferrer';row.dataset.defenseExternal='true';row.setAttribute('aria-label','Захист дисертації '+fullName+' - відкрити інформацію на сайті Університету');const arrow=document.createElement('span');arrow.className='doctoral-defense-arrow';arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');row.append(arrow);}
          item.append(row);items.append(item);
        }
        archiveContent.append(yearFold);
      }
      body.append(archive);
      card.append(body);list.append(card);
    }
    $('reader-content').append(list);return true;
  }

  function renderAccreditation(page){
    if(page.url!=='https://nubip.edu.ua/akredytatsiya-osvitno-naukovykh-prohram')return false;
    const doc=new DOMParser().parseFromString(page.html,'text/html');
    const children=[...doc.body.children],plain=node=>node.textContent.replace(/\s+/g,' ').trim();
    const headings=children.filter(n=>/^Акредитація освітньо-наукової програми/.test(plain(n)));
    if(!headings.length)return false;
    const root=document.createElement('section');root.className='accreditation';
    const tools=document.createElement('div');tools.className='accreditation-search';
    const label=document.createElement('label');label.htmlFor='accreditation-query';label.textContent='Пошук освітньо-наукової програми';
    const input=document.createElement('input');input.id='accreditation-query';input.type='search';input.placeholder='Назва ОНП або спеціальності';input.autocomplete='off';
    const reset=document.createElement('button');reset.type='button';reset.className='secondary';reset.textContent='Скинути';tools.append(label,input,reset);root.append(tools);
    const status=document.createElement('p');status.className='accreditation-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.hidden=true;root.append(status);
    const list=document.createElement('div');list.className='accreditation-list';root.append(list);
    const records=[],extras=[];
    for(let i=0;i<headings.length;i++){
      const heading=headings[i],copy=heading.cloneNode(true);copy.querySelectorAll('br').forEach(n=>n.replaceWith('\n'));
      const text=copy.textContent.replace(/[\t ]+/g,' ').trim(),split=text.search(/\s*спеціальності\s*/i);
      const title=(split>=0?text.slice(0,split):text).replace(/^Акредитація освітньо-наукової програми\s*/,'').trim().replace(/^«\s*|\s*»$/g,'');
      const specialty=split>=0?text.slice(split).trim():'';
      const fold=document.createElement('details');fold.className='accreditation-program';const summary=document.createElement('summary');summary.textContent=title;fold.append(summary);
      const body=document.createElement('div');body.className='accreditation-program-body';
      const start=children.indexOf(heading)+1,end=i+1<headings.length?children.indexOf(headings[i+1]):children.length;
      for(const node of children.slice(start,end)){
        if(node.querySelector('img')){extras.push(node);continue;}
        body.append(...readableFragment(node.outerHTML,page.url));
      }
      fold.append(body);list.append(fold);records.push({fold,text:title+' '+specialty});
    }
    const empty=document.createElement('p');empty.className='accreditation-empty';empty.textContent='За цим запитом програм не знайдено.';empty.hidden=true;root.append(empty);
    const normalize=value=>value.normalize('NFKC').toLocaleLowerCase('uk-UA').replace(/[’ʼ`]/g,"'").replace(/\s+/g,' ').trim();
    const filter=()=>{const words=normalize(input.value).split(' ').filter(Boolean);let found=0;for(const row of records){row.fold.hidden=!words.every(w=>normalize(row.text).includes(w));if(!row.fold.hidden)found++;}status.textContent=words.length?'Знайдено програм: '+found+' із '+records.length:'Освітньо-наукові програми: '+records.length;empty.hidden=found>0;reset.disabled=!input.value;};
    input.addEventListener('input',filter);reset.onclick=()=>{input.value='';filter();input.focus();};filter();
    const related=document.createElement('section');related.className='accreditation-related';const relatedTitle=document.createElement('h3');relatedTitle.textContent='Пов’язані матеріали';related.append(relatedTitle);
    for(const [title,url] of [
      ['Відомості про самооцінювання освітньо-наукових програм','https://nubip.edu.ua/vidomosti-samootsinyuvannya-osvitno-naukovykh-prohram'],
      ['Рекомендації попередніх акредитацій','https://nubip.edu.ua/rekomendatsiyi-poperednikh-akredytatsiy']
    ]){const a=document.createElement('a');a.href=url;a.className='secondary';a.textContent=title;related.append(a);}
    root.append(related);$('reader-content').append(root);return true;
  }

  function renderSelfAssessment(page){
    if(page.url!=='https://nubip.edu.ua/vidomosti-samootsinyuvannya-osvitno-naukovykh-prohram')return false;
    const doc=new DOMParser().parseFromString(page.html,'text/html'),children=[...doc.body.children];
    const yearPattern=/^20\d{2}\s*[–—-]\s*20\d{2}\s+навчальний рік$/;
    if(!children.some(n=>yearPattern.test(n.textContent.trim())))return false;
    const root=document.createElement('div');root.className='self-assessment-years';let body=null;
    for(const node of children){
      const text=node.textContent.replace(/\s+/g,' ').trim();
      if(yearPattern.test(text)){
        const fold=document.createElement('details');fold.className='self-assessment-year';const title=document.createElement('summary');title.textContent=text;fold.append(title);
        body=document.createElement('div');body.className='self-assessment-programs';fold.append(body);root.append(fold);
      }else if(body&&!node.querySelector('img'))body.append(...readableFragment(node.outerHTML,page.url));
    }
    $('reader-content').append(root);return true;
  }

  function renderRecommendations(page){
    if(page.url!=='https://nubip.edu.ua/rekomendatsiyi-poperednikh-akredytatsiy')return false;
    const doc=new DOMParser().parseFromString(page.html,'text/html'),table=doc.querySelector('table');
    if(!table)return false;
    const norm=node=>node.textContent.replace(/\s+/g,' ').trim(),groups=[];let current=null;
    for(const row of table.rows){
      const cells=[...row.cells],texts=cells.map(norm);
      if(cells.length===1&&/^Освітньо-наукова програма/.test(texts[0])){current={title:texts[0],rows:[]};groups.push(current);continue;}
      if(cells.length!==3||texts.every(t=>!t))continue;
      if(/^Недоліки, виявлені/.test(texts[0])&&/Рекомендації/.test(texts[1]))continue;
      if(!current)return false;
      current.rows.push(cells);
    }
    if(!groups.length)return false;
    const root=document.createElement('div');root.className='recommendations-list';
    for(const group of groups){
      const fold=document.createElement('details');fold.className='recommendations-program';
      const title=document.createElement('summary');title.textContent=group.title.replace(/^Освітньо-наукова програма\s*/,'').replace(/^«\s*|\s*»$/g,'');fold.append(title);
      const items=document.createElement('div');items.className='recommendations-items';fold.append(items);
      group.rows.forEach((cells,index)=>{
        const card=document.createElement('article');card.className='recommendation-card';
        const heading=document.createElement('h3');heading.className='recommendation-number';heading.textContent='Пункт '+(index+1);card.append(heading);
        cells.forEach((cell,i)=>{
          const section=document.createElement('section');section.className='recommendation-part recommendation-part-'+i;
          const label=document.createElement('h4');label.textContent=['Недолік','Рекомендація експертів','Виконання'][i];section.append(label);
          const content=document.createElement('div');content.className='recommendation-text';content.append(...readableFragment(cell.innerHTML,page.url));section.append(content);card.append(section);
        });items.append(card);
      });root.append(fold);
    }
    // Keep any textual material outside the source table, retaining the app's image policy.
    const remainder=doc.body.cloneNode(true);remainder.querySelector('table').remove();
    if(remainder.textContent.trim())root.append(...readableFragment(remainder.innerHTML,page.url));
    $('reader-content').append(root);return true;
  }

