  function showReview(){review.replaceChildren();const v=values();for(const [label,value] of [['ПІБ',v.person],['Електронна пошта',v.email],['Телефон',v.phone],['Форма навчання',v.mode],['Факультет / ННІ',v.faculty],['ОНП',clean(program.title)]]){const row=el('div','electives-review-row');row.append(el('small','',label),el('p','',value));review.append(row);}const heading=el('h3','','Обрані дисципліни'),list=el('ol');for(const i of v.choices)list.append(el('li','',program.options[i]));if(v.other)list.append(el('li','','Інша дисципліна: '+v.other));review.append(heading,list);}
  prev.onclick=()=>{if(!active&&!finished)go(step-1);};
